code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-color rows in the framed left panel delimit the independent patterns.
    bounds = [r for r in range(h) if len(set(grid[r][:]) ) == 1 and grid[r][0] != 0]
    # Restrict delimiters to rows whose left panel is uniform and whose right side is empty.
    bounds = [r for r in range(h) if len(set(grid[r][:w//2])) == 1 and grid[r][0] != 0]
    panel_w = w // 2
    inner_w = panel_w - 2
    right_start = panel_w + 1
    right_end = right_start + inner_w
    masks = {}
    for a,b in zip(bounds,bounds[1:]):
        # signatures are the occupied/blank pattern inside each frame
        for r in range(a+1,b):
            pass
        key = tuple(tuple(1 if grid[r][c] == 0 else 0 for c in range(1,panel_w-1)) for r in range(a+1,b))
        colors = {}
        for r in range(a+1,b):
            for c in range(right_start,right_end):
                v=grid[r][c]
                if v: colors[v]=1
        # expected right-hand signature for each color within this panel band
        for color in colors:
            sig=tuple(tuple(1 if grid[r][c]==color else 0 for c in range(right_start,right_end)) for r in range(a+1,b))
            masks[sig]=color
        # record framed pattern for later lookup
        if key not in masks:
            # separate deferred mapping; all exact color signatures gathered globally below
            pass
    color_patterns={}
    for a,b in zip(bounds,bounds[1:]):
        colors={grid[r][c] for r in range(a+1,b) for c in range(right_start,right_end) if grid[r][c]}
        for color in colors:
            sig=tuple(tuple(1 if grid[r][c]==color else 0 for c in range(right_start,right_end)) for r in range(a+1,b))
            color_patterns[sig]=color
    out=[row[:panel_w] for row in grid]
    for a,b in zip(bounds,bounds[1:]):
        pattern=tuple(tuple(1 if grid[r][c]==0 else 0 for c in range(1,panel_w-1)) for r in range(a+1,b))
        color=color_patterns[pattern]
        for rr,r in enumerate(range(a+1,b)):
            for cc,c in enumerate(range(1,panel_w-1)):
                if pattern[rr][cc]: out[r][c]=color
    return out
'''
